INSERT INTO [CuratorReports] (Id,TaskId,CuratorId,ReportText,SubmittedAt,ReviewStatus,ReviewComment) VALUES
(3, 4, 4,N'Отчёт по посещаемости группы ИС-301 за октябрь 2025. Проведено 20 занятий. Средняя посещаемость 89%. Систематически пропускает занятия Захаров Д.М. (3 пропуска). Приняты меры — проведена беседа с куратором.','2025-11-03',N'Принят',      N'Отчёт подробный и своевременный. Принят без замечаний.'),
(4, 5, 5,N'Мероприятие по профориентации прошло 18 ноября. Присутствовало 6 из 7 студентов. Представители компании СберТех рассказали о стажировках. 3 студента выразили желание подать заявку.','2025-11-19',N'Принят',      N'Хорошая инициатива. Продолжайте в том же духе.'),
(5, 6, 6,N'Список задолженностей по группе ПИ-401 составлен. 3 студента имеют задолженности. Проведены индивидуальные беседы с каждым.','2025-10-14',N'Принят',      N'Работа выполнена качественно.'),
(6, 8,14,N'Зачётные книжки группы ВТ-301 проверены. Все 6 студентов имеют оценки за первый модуль. Средний балл по группе 3.8. Рекомендуется уделить внимание студенту Полякову К.Д. по предмету Ассемблер.','2025-10-28',N'Принят',      N'Хорошая проработка.'),
(7,11, 6,N'Контактные данные всех студентов группы ПИ-401 обновлены в системе. Все номера телефонов и адреса электронной почты актуальны.','2025-11-09',N'Принят',      N'Принято.'),
(8, 9, 4,N'Отчёт по посещаемости группы ИС-301 за ноябрь 2025. Средняя посещаемость 91%. Случаев систематических пропусков не выявлено. Группа показывает положительную динамику.','2025-12-03',N'На проверке', NULL),
(9,12,13,N'План кураторских мероприятий для группы ПИ-402 на декабрь: 5 декабря — беседа о зимней сессии, 12 декабря — встреча с работодателями, 20 декабря — подведение итогов семестра.','2025-11-28',N'На проверке', NULL),
(10,4, 4,N'Дополнительный отчёт: в ноябре проведено родительское собрание для группы ИС-301. Присутствовало 5 из 7 родителей. Обсуждены вопросы успеваемости и посещаемости.','2025-11-15',N'Возвращён',   N'Отчёт неполный. Укажите конкретные результаты собрания и принятые решения.');
INSERT INTO [Notifications] (Id,Title,Message,CreatedAt,CreatedBy) VALUES
(4, N'Расписание на октябрь',         N'Расписание занятий на октябрь 2025 года опубликовано. Ознакомьтесь с изменениями в системе.',                    '2025-09-28',2),
(5, N'Сессия: важная информация',     N'Напоминаем, что зимняя сессия начинается 12 января 2026 года. Своевременно ликвидируйте все задолженности.',     '2025-11-01',2),
(6, N'Собрание кураторов',            N'Плановое собрание кураторов состоится 15 ноября в 14:00 в аудитории 204. Явка обязательна.',                      '2025-11-10',3),
(7, N'Напоминание о посещаемости',    N'Обращаем внимание: студенты с более 30% пропусков могут быть отстранены от сессии.',                              '2025-10-15',2),
(8, N'Новый приказ о стипендиях',     N'Опубликован приказ о назначении стипендий за первый модуль. Ознакомьтесь с документом в разделе Документы.',      '2025-10-20',1),
(9, N'Профориентационное мероприятие',N'18 ноября состоится встреча студентов с представителями IT-компаний. Регистрация через куратора группы.',         '2025-11-12',2),
(10,N'Технический перерыв в системе', N'11 ноября с 22:00 до 02:00 система будет недоступна в связи с техническим обслуживанием.',                        '2025-11-08',1),
(11,N'Итоги первого модуля',          N'Итоговые оценки за первый модуль выставлены. Проверьте успеваемость в разделе Оценки.',                            '2025-11-03',3),
(12,N'Конкурс студенческих проектов', N'Объявляется конкурс студенческих проектов. Заявки принимаются до 1 декабря. Подробности у куратора.',              '2025-11-18',2),
(13,N'Изменение в расписании',        N'Внимание: лекция по Математике 25 ноября перенесена с 8:00 на 10:00. Аудитория остаётся прежней.',                 '2025-11-20',3);
