(11,22,N'Справка об обучении',      N'Прошу выдать справку об обучении для получения льготного проездного.',                                         N'Одобрено',        '2025-10-15',3,'2025-10-16',N'Справка готова, можно получить в деканате.'),
(12,34,N'Пересдача экзамена',       N'Прошу назначить пересдачу по Веб-разработке. Болел в день основной сдачи, имеется справка.',                  N'Одобрено',        '2025-10-18',2,'2025-10-20',N'Пересдача назначена на 5 ноября в 14:00.'),
